  Ltac ms_eq := lazymatch goal with |- MS ?r1 ?f1 ?p1 ?c1 ?o1 ?m1 ?x1 = MS ?r2 ?f2 ?p2 ?c2 ?o2 ?m2 ?x2 =>
                  unify r1 r2; unify f1 f2; unify p1 p2; unify c1 c2; unify m1 m2; unify x1 x2; reflexivity end.

  (* [comment removed for export] *)
  Ltac chk_rdz RD := st1; clear RD; st1; livebr1.

  (* [comment removed for export] *)
  Ltac acc_rd ACC MU HW a RD :=
    lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mc _) =>
      pose proof (accessible_rd8 mc a (accessible_sub _ _ _ a 8 (AsWalk.accessible_transport_hi _ _ _ _ _ ACC MU HW) ltac:(lia) ltac:(lia) ltac:(lia)) ltac:(lia)) as RD
