  Ltac chk_acc ACC MU HW a := let RD := fresh "RD" in acc_rd ACC MU HW a RD; chk_rd RD.
  Ltac chk_accz ACC MU HW a := let RD := fresh "RD" in acc_rd ACC MU HW a RD; chk_rdz RD.

  (* [comment removed for export] *)
  Ltac blk_rd ADB DB8 MU WM HW a w RD :=
    pose proof (addressable_rd _ _ _ a w (AsWalk.addressable_transport_hi _ _ _ _ _ ADB MU WM ltac:(aapp_unfold; lia) HW) ltac:(lia) ltac:(lia) ltac:(rewrite DB8; lia)) as RD.
  Ltac chk_blk ADB DB8 MU WM HW a w := let RD := fresh "RD" in blk_rd ADB DB8 MU WM HW a w RD; chk_rd RD.

  (* [comment removed for export] *)
  Ltac chk_globz AC MU WM ACW beg sz szrz a w :=
    lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mc _) =>
      let RD := fresh "RD" in
      pose proof (addressable_rd mc _ _ a w (ACONST_global_addressable mc beg sz szrz (ACONST_frame _ _ _ AC MU WM ACW) ltac:(cbn; tauto) ltac:(lia))
